async function adoptCommandFamilyAuthority(authority, services = {}) {
  const targetContext = services.targetContext || (() => readCommandTargetContext(authority?.defPath, { openDocuments: vscode.workspace.textDocuments || [] }));
  let target = targetContext();
  if (!validateCommandFamilyTarget(authority, target)) throw new Error('The exact character command assignment or command family changed before handoff.');
  await services.beforeOpen?.();
  target = targetContext();
  if (!validateCommandFamilyTarget(authority, target)) throw new Error('The exact command family changed before its workspace could open.');
  const openWorkspace = services.openWorkspace || (() => openCommandMovelistWorkspace(vscode.Uri.file(authority.defPath), { suppressSourceSelection: true }));
  const panel = await openWorkspace();
  await services.afterOpen?.();
  target = targetContext();
  if (!panel || !validateCommandFamilyTarget(authority, target)) throw new Error('The exact command family changed while its workspace was opening.');
  const owner = (services.sessionFor || (candidate => sessions.get(candidate)))(panel);
  if (!owner || owner.disposed || owner.loadedCommandFingerprint !== authority.commandHash || path.resolve(owner.loadedCommandFile || '').toLowerCase() !== path.resolve(authority.commandPath).toLowerCase()) throw new Error('The Command & Movelist workspace is not showing the exact authorized command source.');
  const currentName = owner.commandReference?.command?.name;
  if (owner.clientDraft?.dirty && currentName !== authority.commandName) {
    await vscode.window.showInformationMessage('The command family was not selected because Command & Movelist has unapplied work. The existing draft was kept unchanged.');
    return { opened: true, dispatched: false, reason: 'unapplied-command-draft' };
  }
  const sent = await panel.webview.postMessage({ type: 'commandSourceLine', file: authority.commandPath, referenceName: authority.commandName, occurrence: 0, familyCount: authority.familyCount });
  return { opened: true, dispatched: sent !== false, name: authority.commandName, familyCount: authority.familyCount };
}

async function openCommandMovelistWorkspace(uri, options = {}, navigationReference) {
  let seed = uri && uri.fsPath || vscode.window.activeTextEditor && vscode.window.activeTextEditor.document.uri.fsPath;
  if (!seed) seed = await chooseCharacterDef(undefined, { title: 'Command & Movelist — Character' });
  if (!seed) return;
  const invokedFile = path.resolve(seed), editor = vscode.window.activeTextEditor;
  const sourceSelection = typeof options?.referenceName==='string'&&options.referenceName.length>0&&options.referenceName.length<=512&&!/[\r\n\"]/.test(options.referenceName)?{referenceName:options.referenceName}:!options?.suppressSourceSelection && editor && editor.document && path.resolve(editor.document.uri.fsPath || editor.document.fileName || '').toLowerCase() === invokedFile.toLowerCase()
    ? (() => {
      const line = Number(editor.selection?.active?.line) || 0, character = Number(editor.selection?.active?.character) || 0, extension = path.extname(invokedFile).toLowerCase();
      if (['.cmd', '.inp', '.jnp'].includes(extension)) {
        const parsed = parseCommands(editor.document.getText(), invokedFile), command = parsed.commands.find(item => line >= item.startLine && line < item.endLine);
        if (command) { const signature = JSON.stringify(commandValues(command)), occurrence = parsed.commands.slice(0, parsed.commands.indexOf(command)).filter(item => JSON.stringify(commandValues(item)) === signature).length; return { commandFile: invokedFile, line, command: commandValues(command), occurrence }; }
      }
      if (['.zss', '.cns', '.st', '.cmd', '.inp', '.jnp'].includes(extension)) {
        const sourceLine = editor.document.lineAt(line).text, reference = commandReferenceAtPosition(sourceLine, character, { semicolonComments: extension !== '.zss' });
        if (reference && !reference.redirected) return { referenceName: reference.name };
        if (['.zss', '.cns', '.st'].includes(extension) && typeof editor.document.offsetAt === 'function') {
          const offset = editor.document.offsetAt(editor.selection.active), occurrences = commandInputOccurrencesForSource({ filename: invokedFile, syntax: extension === '.zss' ? 'zss' : 'cns', text: editor.document.getText() });
          const controller = occurrences.find(item => item.relation === 'command-assert' && item.commandName && offset >= item.start && offset <= item.end);
          if (controller) return { referenceName: controller.commandName };
        }
      }
      return ['.cmd', '.inp', '.jnp'].includes(extension) ? { commandFile: invokedFile, line } : {};
    })() : {};
  const requestedMovelistFile=path.extname(invokedFile).toLowerCase()==='.dat'?invokedFile:navigationReference?.tab==='movelist'?navigationReference.file:'';
  const preferred = vscode.workspace.getConfiguration('ikemenZss').get('defaultTrainingCharacter', '');
  let owners = commandOwnerCandidates(invokedFile, preferred);
  if (owners.length === 1) seed = owners[0];
  else if (owners.length > 1) {
    const selected = await vscode.window.showQuickPick(owners.map((filename) => ({ label: path.basename(filename, '.def'), description: filename, filename })), { title: 'Choose the character whose commands and movelist you want to edit', matchOnDescription: true });
    if (!selected) return;
    owners = commandOwnerCandidates(invokedFile, preferred);
    if (!owners.some(filename => path.resolve(filename).toLowerCase() === path.resolve(selected.filename).toLowerCase())) return vscode.window.showInformationMessage('The selected character no longer owns this command or asset source. Nothing was opened.');
    seed = selected.filename;
  }
  else return vscode.window.showInformationMessage('This file is not assigned to one character DEF. Open it through Character Essentials or choose an owner from Connected Resources.');
  const targetColumn = await focusedVisualWorkspaceColumn(vscode.ViewColumn.Active);
  const existing = openPanels.get(panelKey(seed));
  if (existing) { existing.reveal(targetColumn, false); if(options?.focusCommandDefinitions) await existing.webview.postMessage({type:'focusCommandDefinitions'}); if(requestedMovelistFile)await enqueuePopulate(existing,seed,{movelistFile:requestedMovelistFile,selectedReference:movelistReference(currentText(requestedMovelistFile),0,requestedMovelistFile)});if (sourceSelection.commandFile || sourceSelection.referenceName) await existing.webview.postMessage({ type: 'commandSourceLine', ...sourceSelection }); return existing; }
  const panel = trackViewerPanel(vscode.window.createWebviewPanel('ikemenCommandMovelist', 'Command & Movelist', targetColumn, { enableScripts: true, retainContextWhenHidden: true }));
  await populate(panel, seed, {...sourceSelection,movelistFile:requestedMovelistFile});
  return panel;
}

async function openMotionRecipes(uri) {
  const seed = uri?.fsPath || await chooseCharacterDef(undefined, { title: 'Command triggers — Character' });
  if (!seed) return;
  const { commandFile } = contextFiles(seed, currentText);
  const commands = commandFile ? parseCommands(currentText(commandFile), commandFile).commands : [];
  const showCommandMaker = () => openCommandMovelistWorkspace(vscode.Uri.file(seed), { focusCommandDefinitions: true });
  const openMaker = { label: 'Open Command Maker…', description: 'Create or edit inputs for this character', maker: true };
  const recipes = [
    { label: 'Grounded motion', description: 'One command · includes standing and crouching', posture: 'grounded' },
    { label: 'Grounded motion with absolute left/right inputs', description: 'Choose one command for each facing direction', posture: 'grounded', paired: true },
    { label: 'Airborne motion', description: 'One command · airborne only', posture: 'airborne' },
    { label: 'Unrestricted input', description: 'One command · any posture or fixed screen direction', posture: 'any' }
  ];
  const title = 'Command triggers · ' + path.basename(seed);
  const recipe = await vscode.window.showQuickPick(commands.length ? [...recipes, openMaker] : [openMaker], { title, placeHolder: commands.length ? 'Choose a built-in recipe' : 'Create a named input for this character first' });
  if (!recipe) return;
  if (recipe.maker) return showCommandMaker();
  const families = new Map();
  for (const command of commands) {
    if (!command.name || !command.command) continue;
    if (!families.has(command.name)) families.set(command.name, new Set());
    families.get(command.name).add(command.command);
  }
  const choices = Array.from(families, ([label, motions]) => ({ label, description: [...motions].join(' / ') }));
  const pick = placeHolder => vscode.window.showQuickPick([...choices, openMaker], { title, placeHolder, matchOnDescription: true });
  const right = await pick(recipe.paired ? 'Choose the input used when facing right' : 'Choose the input that starts the move');
  if (!right || right.maker) return right && showCommandMaker();
  let left;
  if (recipe.paired) {
    const mirrors = new Set([...families.get(right.label)].map(mirroredAbsoluteMotion).filter(Boolean));
    const candidates = choices.map(item => {
      const matches = [...families.get(item.label)].some(sequence => mirrors.has(commandStepLayout(sequence).steps.map(step => normalizeCommandStepForReview(step.core)).join(',')));
      return matches ? { ...item, detail: 'Matches the mirrored input sequence' } : item;
    });
    candidates.sort((a, b) => Number(Boolean(b.detail)) - Number(Boolean(a.detail)));
    left = await vscode.window.showQuickPick([...candidates, openMaker], { title, placeHolder: 'Choose the input used when facing left', matchOnDescription: true });
  }
  if (recipe.paired && (!left || left.maker)) return left && showCommandMaker();
  const expression = motionCommandTrigger(recipe.paired ? { posture: recipe.posture, rightName: right.label, leftName: left.label } : { posture: recipe.posture, name: right.label });
  const format = await vscode.window.showQuickPick([
    { label: 'Copy condition', description: 'Use in ZSS or an existing trigger expression', text: expression },
    { label: 'Copy CNS trigger line', description: 'Paste into a state controller', text: 'trigger1 = ' + expression }
  ].map(item => ({ ...item, detail: item.text })), { title, placeHolder: 'Review and copy the trigger' });
  if (format) {
    await vscode.env.clipboard.writeText(format.text);
    vscode.window.setStatusBarMessage('Command trigger copied.', 3000);
  }
}

function registerCommandMovelistWorkspace(context, options = {}) {
  extensionContext = context;
  workspaceOptions = options;
  context.subscriptions.push(
    vscode.commands.registerCommand('ikemen.moveLab.commandTriggerRecipes', openMotionRecipes),
    vscode.commands.registerCommand('ikemen.commandMovelist.openEditor', openCommandMovelistWorkspace),
    vscode.window.registerWebviewPanelSerializer('ikemenCommandMovelist', { async deserializeWebviewPanel(panel, state) { if (!state || !state.seed || !exists(state.seed)) { panel.dispose(); return; } await populate(panel, state.seed,{movelistFile:state.movelistFile}); } }),
    require('./engine_capability_events').onDidChangeEngineCapabilities(() => {
      for (const panel of openPanels.values()) {
        const session = sessions.get(panel);
        if (session && !session.disposed) enqueuePopulate(panel, session.seed, {}).catch(() => undefined);
      }
    })
  );
}

